const normalize = (t) => t.normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const question = $json.question;
const q = ` ${normalize(question)} `;
// Termes les plus longs d'abord : « Notes de frais » avant « Notes ».
const hints = GLOSSARY
  .filter((t) => { const n = normalize(t.fr); return n.length >= 3 && q.includes(` ${n} `); })
  .sort((a, b) => b.fr.length - a.fr.length)
  .slice(0, 8);

const glossary = hints.length
  ? `\nCorrespondances des libellés d'Odoo (français → anglais), à utiliser dans les sous-questions : ${hints.map((h) => `${h.fr} → ${h.en.join(' / ')}`).join(' ; ')}.\n`
  : '';

// Mode config : un besoin client couvre souvent plusieurs fonctions (ex. intervention + rapport signé + facturation).
const maxSub = $json.mode === 'config' ? 7 : 5;
const prompt = `Version Odoo : 20.0.
Question du consultant : « ${question} »
${glossary}
Produis "subQuestions" : la question décomposée en sous-questions de recherche en anglais, une par module ou par étape fonctionnelle (ex. pour vente → livraison → facture → paiement : une pour la configuration préalable, une par étape). Une seule si la question est simple, ${maxSub} au maximum${maxSub > 5 ? ', une par fonction à paramétrer' : ''}. Chaque sous-question est une phrase précise avec les termes exacts de l'interface et de la documentation Odoo (ex. "How to register a payment on a customer invoice").`;

return {
  json: {
    question,
    model: $json.model,
    glossaryHints: hints,
    planBody: {
      model: 'claude-haiku-5-5',
      max_tokens: 600,
      system: "Tu prépares une recherche dans la documentation officielle d'Odoo (rédigée en anglais).",
      messages: [{ role: 'user', content: prompt }],
      tools: [{
        name: 'search_plan',
        description: 'Sous-questions de recherche en anglais',
        input_schema: {
          type: 'object',
          properties: { subQuestions: { type: 'array', items: { type: 'string' }, minItems: 1, maxItems: maxSub } },
          required: ['subQuestions'],
        },
      }],
      tool_choice: { type: 'tool', name: 'search_plan' },
    },
  },
};

// Why Code: lecture du plan renvoyé par Claude (outil forcé) et construction du lot d'embeddings (préfixe de tâche propre à gemini-embedding-2).
const input = $('Build plan request').first().json;
const tool = ($json.content ?? []).find((c) => c.type === 'tool_use');
let subQuestions = tool?.input?.subQuestions ?? [];
subQuestions = subQuestions.filter((s) => typeof s === 'string' && s.trim()).slice(0, $('Normalize input').first().json.mode === 'config' ? 7 : 5);

// La question d'origine d'abord, puis chaque sous-question : chacune apporte ses passages à tour de rôle.
const queries = [input.question, ...subQuestions];
// gemini-embedding-2 n'accepte pas taskType : la tâche est donnée en préfixe (« task: … | query: … »).
const embedBody = {
  requests: queries.map((q) => ({
    model: 'models/gemini-embedding-2',
    content: { parts: [{ text: `task: question answering | query: ${q}` }] },
    outputDimensionality: 1536,
  })),
};

return { json: { question: input.question, model: input.model, subQuestions, queries, embedBody } };

