-- materialized : chaque vecteur est converti une seule fois (sinon la conversion texte → vector est refaite à chaque ligne).
with q as materialized (
  select t.ord, t.v::vector as vec
  from jsonb_array_elements_text($1::jsonb) with ordinality as t(v, ord)
)
select q.ord, r.*
from q cross join lateral (
  select n.chunk_id, n.source_id, s.kind, s.title, n.breadcrumb, n.url, s.url_fr, n.content, n.similarity
  from (
    select c.id as chunk_id, c.source_id, c.breadcrumb, c.url, c.content, 1 - (c.embedding <=> q.vec) as similarity
    from knowledge_chunks c
    where c.odoo_version = '20.0'
    order by c.embedding <=> q.vec
    limit 80
  ) n join knowledge_sources s on s.id = n.source_id
  where s.kind in ('odoo_documentation', 'youtube_video') and s.status = 'ingested'
  order by n.similarity desc
  limit 40
) r
order by q.ord, r.similarity desc

