// Why Code: sélection diversifiée à tour de rôle entre plusieurs listes avec plafond par page, qu'aucun nœud natif n'exprime.
const plan = $('Build embed request').first().json;
const lists = plan.queries.map(() => []);
for (const item of $input.all()) {
  const r = item.json;
  if (r.ord) lists[Number(r.ord) - 1].push(r);
}

// Chaque liste (question, puis sous-questions) apporte à tour de rôle son meilleur passage pas encore retenu,
// sans dépasser PER_PAGE passages par page : aucune page ne peut occuper toute la sélection.
// Mode config : pages de procédure longues (ex. field_service, sla) : plus de passages par page.
const config = $('Normalize input').first().json.mode === 'config';
const LIMIT = config ? 16 : plan.subQuestions.length > 1 ? 12 : 8;
const PER_PAGE = config ? 5 : 3;
const chosen = [];
const ids = new Set();
const perSource = new Map();
const cursors = lists.map(() => 0);
while (chosen.length < LIMIT) {
  let progressed = false;
  for (let i = 0; i < lists.length && chosen.length < LIMIT; i++) {
    const list = lists[i];
    while (cursors[i] < list.length && (ids.has(list[cursors[i]].chunk_id) || (perSource.get(list[cursors[i]].source_id) ?? 0) >= PER_PAGE)) cursors[i]++;
    if (cursors[i] >= list.length) continue;
    const row = list[cursors[i]++];
    ids.add(row.chunk_id);
    perSource.set(row.source_id, (perSource.get(row.source_id) ?? 0) + 1);
    chosen.push({ row, query: i });
    progressed = true;
  }
  if (!progressed) break;
}

const passages = chosen.map(({ row, query }, i) => ({
  n: i + 1,
  chunkId: row.chunk_id,
  kind: row.kind,
  title: row.title,
  breadcrumb: row.breadcrumb,
  url: row.url,
  urlFr: row.url_fr,
  similarity: Math.round(Number(row.similarity) * 1000) / 1000,
  query,
  content: row.content,
}));
const bestSimilarity = lists[0]?.[0] ? Number(lists[0][0].similarity) : null;

// Mode config : pages dont au moins 3 passages sont retenus (2 au plus), à charger en entier.
const fullPages = !config ? [] : [...perSource.entries()].filter(([, k]) => k >= 3).sort((x, y) => y[1] - x[1]).slice(0, 2).map(([id]) => id);
return [{ json: { question: plan.question, model: plan.model, subQuestions: plan.subQuestions, bestSimilarity, passages, fullPages } }];

// Why Code: prompt de rédaction (consignes de l'ancien projet), passages numérotés et corps de requête propre au fournisseur.
const RULES = `Tu es l'assistant d'un consultant fonctionnel Odoo. Tu réponds en français, pour Odoo 20.0 uniquement.

Règles impératives :
1. Appuie-toi sur les passages numérotés fournis. Chaque élément de "summary", "prerequisites", "steps" et "warnings" cite dans "sources" les numéros des passages qui l'appuient : ces éléments seront présentés comme DOCUMENTÉS, puis contrôlés sur la page officielle en ligne.
2. Une citation doit soutenir précisément l'affirmation, dans son contexte :
   - ne généralise pas un passage qui décrit un cas particulier : une localisation fiscale (un pays), un exemple chiffré, une migration de version, ou un autre flux (ex. sous-traitance en dropship pour une question de sous-traitance avec réapprovisionnement) ;
   - ne présente pas comme obligatoire ce que le passage présente comme possible, optionnel ou « par défaut » ;
   - si un réglage n'est cité que dans un autre contexte, ne l'inclus pas, ou mets-le dans "hypotheses".
3. N'invente jamais de menu, de champ, de paramètre ou de module documenté. Une information utile absente des passages va dans "hypotheses" (À VÉRIFIER) ou dans "gaps" (NON COUVERT), jamais dans les étapes.
4. Recopie les libellés d'interface et les chemins de menu exactement comme dans les passages (en anglais, entre ** **), sans les traduire ; tu peux ajouter une explication en français.
5. "steps" : instructions documentées, dans l'ordre, une action par étape, avec le chemin de menu complet quand il est connu. Pour un processus qui traverse plusieurs modules, couvre chaque étape pour laquelle un passage existe.
6. "coverage" : "complete" si les passages répondent entièrement, "partial" s'ils répondent en partie, "insufficient" s'ils ne permettent pas de répondre (dans ce cas, dis-le dans "summary" et ne mets dans "steps" que ce qui est documenté).
7. "hypotheses" : quand la documentation est insuffisante ou partielle, tu peux proposer des pistes de solution à tester. Chacune commence par « Piste à tester : », s'appuie sur des fonctions standard, et ne doit jamais être présentée comme une fonctionnalité native confirmée. Laisse la liste vide si les passages suffisent.
8. "gaps" : ce que ni les passages ni les pistes ne couvrent.
9. "warnings" : limites, prérequis d'édition (Enterprise / Community) ou effets de bord signalés par les passages.
10. Odoo évolue à chaque version : quand un passage présente un élément comme une nouveauté ou un changement (« As of Odoo 19.0 », « new in Odoo 20 »), dis-le dans "warnings". Si la question vise une autre version qu'Odoo 20 (17, 18, 19…), dis-le dans "warnings" : les passages décrivent Odoo 20 et la procédure peut différer dans cette version.
11. Les passages marqués « vidéo » sont des transcripts automatiques des vidéos Odoo Tutorials, non relus : cite-les seulement pour ce que la documentation ne couvre pas.
12. Si la question ne porte pas sur Odoo, ou si aucun passage ne s'y rapporte : "coverage" vaut "insufficient", "summary" le dit sans citer de source, "steps" reste vide.`;

// Mode QCM : la question arrive suivie de ses choix lettrés (A., B., C.…).
const norm = $('Normalize input').first().json;
const qcm = norm.mode === 'qcm';
const letters = norm.choix.map((_, i) => String.fromCharCode(65 + i));
const QCM_RULES = `

Mode QCM : la question est une question à choix multiples de la certification Odoo, souvent écrite pour Odoo 19, suivie de ses choix lettrés.
13. "answer_letters" : la ou les lettres des bonnes réponses pour Odoo 20, d'après les passages. Une seule lettre, sauf si l'énoncé demande plusieurs réponses ou si plusieurs choix sont vrais selon les passages. Si les passages ne permettent pas de trancher, donne le choix le plus probable, mets "coverage" à "partial" ou "insufficient" et explique ton raisonnement dans "hypotheses".
14. "summary" : l'explication courte du choix, avec ses sources. Les autres listes restent courtes : pas de procédure complète, seulement ce qui justifie la réponse.
15. "version_gap" : si les passages d'Odoo 20 montrent qu'un élément de la question ou des choix a changé (libellé renommé, option supprimée, comportement différent d'Odoo 19), décris l'écart en une phrase ; sinon chaîne vide.`;
// Mode config : un besoin client à traduire en étapes de paramétrage.
const config = norm.mode === 'config';
const CONFIG_RULES = `

Mode configuration : la question est un besoin client à paramétrer dans Odoo 20.0, suivie des données client quand il y en a.
13. "steps" : une étape par opération de paramétrage (activer un réglage, renseigner un champ, créer un enregistrement), dans l'ordre d'exécution, prérequis compris : le réglage avant le champ qu'il fait apparaître, l'enregistrement créé avant d'être sélectionné. Pour chaque étape :
   - "title" : l'action, verbe et objet, en français (ex. « Activer la route MTO ») ;
   - "menu" : le chemin de menu complet en anglais, tel que dans les passages (ex. **Inventory app ‣ Configuration ‣ Settings**) ; chaîne vide s'il n'est pas documenté ;
   - "champ" : le libellé exact du champ, de l'onglet ou de la case, en anglais ; chaîne vide s'il n'y en a pas ;
   - "valeur" : la valeur à saisir ou à sélectionner, en anglais pour une option d'Odoo (ex. **Replenish on Order (MTO)**), ou une donnée recopiée telle quelle des données client. Une donnée métier absente des données client (prix, délai, quantité, nom) s'écrit « À renseigner » : n'en invente jamais. Place chaque donnée client dans le champ qui lui correspond : le délai annoncé d'un fournisseur va dans le délai d'achat de ce fournisseur, jamais dans le délai de livraison au client. Applique chaque donnée client seulement à l'objet auquel les données client la rattachent (indiqué entre parenthèses), jamais à un autre, et ne propose pas d'étape conditionnelle (« si le produit est aussi acheté chez… »).
   Quand un passage décrit une procédure (ex. « enable the **Purchase** checkbox… then… »), reprends chacune de ses opérations en étape (case à cocher, onglet, champ), sans en sauter.
14. Ne propose que ce que le besoin demande : aucun réglage avancé (routes multi-étapes, contrôle qualité, autre édition) que le besoin n'exige pas. Une décision que le client n'a pas prise va dans "gaps".
15. Signale dans "warnings" l'édition requise (Enterprise) quand un passage l'indique.
16. Si deux passages se contredisent et que l'un décrit un changement de version (« As of Odoo 19.0 », « masqué par défaut depuis… »), suis le changement le plus récent, ne reprends pas l'instruction ancienne, et signale le conflit dans "warnings".`;
const cited = { type: 'object', properties: { text: { type: 'string' }, sources: { type: 'array', items: { type: 'integer' } } }, required: ['text', 'sources'], additionalProperties: false };
const ANSWER_SCHEMA = {
  type: 'object',
  properties: {
    summary: cited,
    prerequisites: { type: 'array', items: cited },
    steps: { type: 'array', items: { type: 'object', properties: { title: { type: 'string' }, detail: { type: 'string' }, sources: { type: 'array', items: { type: 'integer' } } }, required: ['title', 'detail', 'sources'], additionalProperties: false } },
    warnings: { type: 'array', items: cited },
    coverage: { type: 'string', enum: ['complete', 'partial', 'insufficient'] },
    hypotheses: { type: 'array', items: { type: 'string' } },
    gaps: { type: 'array', items: { type: 'string' } },
  },
  required: ['summary', 'prerequisites', 'steps', 'warnings', 'coverage', 'hypotheses', 'gaps'],
  additionalProperties: false,
};
if (qcm) {
  ANSWER_SCHEMA.properties.answer_letters = { type: 'array', items: { type: 'string', enum: letters }, minItems: 1 };
  ANSWER_SCHEMA.properties.version_gap = { type: 'string' };
  ANSWER_SCHEMA.required.push('answer_letters', 'version_gap');
}
if (config) {
  ANSWER_SCHEMA.properties.steps.items = { type: 'object', properties: { title: { type: 'string' }, menu: { type: 'string' }, champ: { type: 'string' }, valeur: { type: 'string' }, detail: { type: 'string' }, sources: { type: 'array', items: { type: 'integer' } } }, required: ['title', 'menu', 'champ', 'valeur', 'detail', 'sources'], additionalProperties: false };
}
const SYSTEM = qcm ? RULES + QCM_RULES : config ? RULES + CONFIG_RULES : RULES;
// Gemini n'accepte pas forcément additionalProperties : retiré de sa copie du schéma.
const withoutAdditional = (s) => JSON.parse(JSON.stringify(s, (k, v) => (k === 'additionalProperties' ? undefined : v)));

const blocks = $json.passages.map((p) => `[${p.n}] ${p.kind === 'youtube_video' ? `(vidéo Odoo Tutorials, transcript automatique) ${p.title}` : p.breadcrumb}\n${p.content}`).join('\n\n---\n\n');
